(()=>{'use strict';const $=s=>document.querySelector(s),rows=[...document.querySelectorAll('#items .item')],cats=$('#cats'),search=$('#search');document.body.classList.remove('no-js');let active='Tout',family=null;const families={morning:['Coffee','Thé noir','Thé vert','Infusions','Latte Signature','Cosy Breakfast','Desserts'],food:['Burgers','Salades','Snacking','Planches'],evening:['Bar','Cocktails','Mocktails','Bubble Tea','Bubble Shake','Brown Sugar','Planches']};const norm=v=>v.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();function render(){let n=0;for(const r of rows){r.hidden=!((active==='Tout'||r.dataset.category===active)&&(!family||families[family].includes(r.dataset.category))&&norm(r.textContent+' '+r.dataset.category).includes(norm(search.value.trim())));if(!r.hidden)n++}for(const g of document.querySelectorAll('.menu-category')){g.hidden=![...g.querySelectorAll('.item')].some(r=>!r.hidden);if(!g.hidden&&(active!=='Tout'||family||search.value.trim()))g.open=true;}for(const b of cats.children)b.setAttribute('aria-pressed',String(!family&&b.dataset.category===active));$('#menu-empty').hidden=n!==0;document.querySelectorAll('[data-family]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.family===family)));const term=search.value.trim(),names={'Coffee':'Cafés & boissons chaudes','Cosy Breakfast':'Petits-déjeuners'},familyNames={morning:'Café & breakfast',food:'À table',evening:'Après le travail'},scope=term?'Recherche : « '+term+' »':family?familyNames[family]:active!=='Tout'?(names[active]||active):'Toutes les catégories';$('#reset').textContent=term||family||active!=='Tout'?'Effacer les filtres':'Voir toute la carte';$('#count').textContent=scope+' · '+n+(term||family||active!=='Tout'?' sur '+rows.length:'')+' référence'+(n===1?'':'s');}for(const c of ['Tout',...new Set(rows.map(r=>r.dataset.category))]){const b=document.createElement('button');b.type='button';b.dataset.category=c;b.setAttribute('aria-controls','items');b.textContent=({'Coffee':'Cafés','Cosy Breakfast':'Petits-déjeuners'})[c]||c;b.addEventListener('click',()=>{active=c;family=null;search.value='';render()});cats.append(b)}search.addEventListener('input',()=>{active='Tout';family=null;render()});$('#reset').addEventListener('click',()=>{active='Tout';family=null;search.value='';render();search.focus()});document.querySelectorAll('[data-cat]').forEach(a=>a.addEventListener('click',()=>{active=a.dataset.cat;family=null;search.value='';render()}));document.querySelectorAll('[data-family]').forEach(b=>b.addEventListener('click',()=>{family=family===b.dataset.family?null:b.dataset.family;active='Tout';search.value='';render()}));function hours(){const parts=new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/Paris',weekday:'short',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(new Date()),get=t=>parts.find(p=>p.type===t)?.value,d=get('weekday'),h=Number(get('hour'))+Number(get('minute'))/60;$('#open').textContent=d!=='Mon'&&h>=(d==='Sun'?10:8)&&h<(d==='Sun'?17:22)?'Ouvert selon les horaires habituels':'Fermé selon les horaires habituels'}hours();setInterval(hours,60000);render()})();
;(()=>{'use strict';const choices=document.querySelectorAll('[data-moment]'),feature=document.querySelector('.dayfeature'),image=document.querySelector('#moment-image'),title=document.querySelector('#moment-title'),copy=document.querySelector('#moment-copy'),link=document.querySelector('#moment-link');const moments={am:['data:image/webp;base64,','Café Cosy Corner','Le matin prend son temps.','Breakfast, café et douceurs.','Cosy Breakfast'],pm:['data:image/webp;base64,','Verre et sous-verre Cosy Corner','Le soir, on se retrouve.','Cocktails, mocktails et planches.','Mocktails']};for(const b of choices)b.addEventListener('click',()=>{const m=moments[b.dataset.moment];for(const x of choices)x.setAttribute('aria-pressed',String(x===b));image.src=m[0];image.alt=m[1];title.textContent=m[2];copy.textContent=m[3];link.dataset.cat=m[4];feature.getAnimations?.().forEach(x=>x.cancel());if(!matchMedia('(prefers-reduced-motion: reduce)').matches)feature.animate?.([{opacity:.65,transform:'translateY(6px)'},{opacity:1,transform:'none'}],{duration:200,easing:'ease-out'})})})();

