(()=>{const links=[...document.querySelectorAll('#main-nav a[href^="#"]')];const sections=links.map(a=>document.querySelector(a.getAttribute('href')));let pending=false;function update(){pending=false;const top=document.querySelector('header').getBoundingClientRect().bottom+Math.max(24,parseFloat(getComputedStyle(document.documentElement).scrollPaddingTop)||0)+Math.max(0,...sections.map(el=>parseFloat(getComputedStyle(el).scrollMarginTop)||0));let current=-1;sections.forEach((el,i)=>{if(el&&el.getBoundingClientRect().top<=top)current=i});links.forEach((a,i)=>{if(i===current)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current')})}function request(){if(!pending){pending=true;requestAnimationFrame(update)}}addEventListener('scroll',request,{passive:true});addEventListener('resize',request);addEventListener('load',request);request()})();